<?php
declare(strict_types=1);
$directory=$argv[1];$starter=$argv[2];require $directory.'/vendor/autoload.php';$app=require $directory.'/bootstrap/app.php';
use Symfony\Component\HttpFoundation\{Request,Session\Session,Session\Storage\MockArraySessionStorage};
function check(bool $success,string $message):void { if(!$success) throw new RuntimeException($message); }
$session=new Session(new MockArraySessionStorage());
$browser=function(string $path,string $method='GET',array $input=[])use($app,$session) { $request=Request::create($path,$method,$input);$request->setSession($session);return $app->handle($request); };
check(in_array($browser('/')->getStatusCode(),$starter==='dashboard'?[302,303]:[200],true),'home');check($browser('/login')->getStatusCode()===200,'login');
$users=$app->container->get(Elang\Auth\Users::class);$auth=$app->container->get(Elang\Auth\Auth::class);$suffix=bin2hex(random_bytes(4));$one=$users->create('First','first'.$suffix.'@example.com','Testing passphrase one 123','user',true);$two=$users->create('Second','second'.$suffix.'@example.com','Testing passphrase two 456','user',true);
$request=Request::create('/');$request->setSession($session);$auth->login($request,$one);check($browser('/dashboard')->getStatusCode()===200,'account');$csrf=$session->get('_csrf');
if($starter==='api') {
    $tokens=$app->container->get(Elang\Auth\ApiTokens::class);$writer=$tokens->issue($one,'writer',['notes:read','notes:write']);$reader=$tokens->issue($one,'reader',['notes:read']);$other=$tokens->issue($two,'other',['notes:read','notes:write']);
    $api=function(string $path,string $method='GET',?array $json=null,?string $token=null,array $headers=[])use($app,$writer) { $request=Request::create($path,$method,[],[],[],['CONTENT_TYPE'=>'application/json'],$json===null?null:json_encode($json));$request->headers->add(['Accept'=>'application/json','Authorization'=>'Bearer '.($token??$writer)]+$headers);return $app->handle($request); };
    $first=$api('/api/notes','POST',['title'=>'Private note','body'=>'Body','owner_id'=>$two->id],null,['Idempotency-Key'=>'create-unique-'.$suffix]);check($first->getStatusCode()===201,'create: '.$first->getContent());$id=json_decode($first->getContent(),true)['data']['id'];$repeat=$api('/api/notes','POST',['title'=>'Private note','body'=>'Body','owner_id'=>$two->id],null,['Idempotency-Key'=>'create-unique-'.$suffix]);check($repeat->headers->get('Idempotency-Replayed')==='true','idempotency');check($api('/api/notes/'.$id,'GET',null,$other)->getStatusCode()===404,'owner read');check($api('/api/notes/'.$id,'DELETE',null,$other)->getStatusCode()===404,'owner delete');check($api('/api/notes','POST',['title'=>'Denied'],$reader)->getStatusCode()===403,'write scope');check($api('/api/notes','POST',['title'=>''])->getStatusCode()===422,'validation');check($api('/api/notes?page=invalid')->getStatusCode()===400,'page validation');check($api('/api/notes/'.$id,'PUT',['title'=>'Updated'])->getStatusCode()===200,'update');check(count($app->container->get(Elang\Realtime\Events::class)->after('user:'.$one->id.':notes'))===2,'atomic events');check($browser('/openapi.json')->getStatusCode()===200,'openapi');
    $socket=json_decode($api('/api/realtime-token','POST',[])->getContent(),true);check(isset($socket['token']),'socket capability');check($api('/api/notes/'.$id,'DELETE')->getStatusCode()===204,'delete');
    file_put_contents($directory.'/storage/qa-tokens.json',json_encode(['writer'=>$writer,'reader'=>$reader,'other'=>$other,'socket'=>$socket['token'],'user'=>$one->id]));chmod($directory.'/storage/qa-tokens.json',0600);
} elseif($starter==='blog') {
    check($browser('/posts/new')->getStatusCode()===200,'new article');$response=$browser('/posts','POST',['_token'=>$csrf,'title'=>'A safe article','body'=>'<script>evil()</script>','published'=>'1']);check($response->getStatusCode()===303,'save article: '.$response->getContent());preg_match('~/posts/(\d+)/edit~',$response->headers->get('Location'),$match);$id=(int)$match[1];$public=$browser('/posts/'.$id);check($public->getStatusCode()===200,'published article');check(!str_contains($public->getContent(),'<script>evil()</script>'),'HTML escaping');$auth->login($request,$two);check($browser('/posts/'.$id.'/edit')->getStatusCode()===404,'article owner');
} elseif($starter==='dashboard') {
    check($browser('/workspace')->getStatusCode()===200,'workspace');check($browser('/workspace/notes','POST',['_token'=>$csrf,'title'=>'Private workspace note','body'=>'Saved'])->getStatusCode()===303,'create note');$id=(int)$app->container->get(Elang\Database\Database::class)->connection()->fetchOne('SELECT MAX(id) FROM notes');$auth->login($request,$two);$browser('/workspace');check($browser('/workspace/notes/'.$id.'/delete','POST',['_token'=>$session->get('_csrf')])->getStatusCode()===404,'workspace owner');
}
echo $starter.": installation, pages, authorization, and domain operations passed\n";
